class MockResponse extends Writable {
  constructor() { super(); this.headers = {}; this.statusCode = 0; this.headersSent = false; this.parts = []; }
  writeHead(status, headers = {}) { this.statusCode = status; this.headers = headers; this.headersSent = true; return this; }
  _write(chunk, _encoding, callback) { this.parts.push(Buffer.from(chunk)); callback(); }
  get bodyBuffer() { return Buffer.concat(this.parts); }
  get body() { return this.bodyBuffer.toString('utf8'); }
}

async function call(handle, method, url, { body = null, cookie = '', contentType = 'application/json', remoteAddress = '127.0.0.1', raw = false } = {}) {
  if(method==='POST'&&url==='/api/leads'&&!/(?:^|;\s*)zezo_session=/.test(cookie)&&!raw&&body&&typeof body==='object'&&!Buffer.isBuffer(body)){
    const fields=body,email=String(fields.email||'test-client@example.test').toLowerCase(),session=await ensureTestClient(handle,{name:fields.name||'Test Client',email,referralCode:fields.referralCode,referralVisitorId:fields.referralVisitorId});
    cookie=[session.cookie,cookie].filter(Boolean).join('; ');
    if(!/^\+[1-9]\d{7,14}$/.test(String(fields.phone||''))){const digits=[...email].reduce((sum,char)=>sum+char.charCodeAt(0),0).toString().padStart(8,'0').slice(-8);fields.whatsappCountryCode='+971';fields.whatsappLocalNumber='5'+digits;fields.phone='';}
  }
  const req = Readable.from(body == null ? [] : [Buffer.isBuffer(body) ? body : Buffer.from(typeof body === 'string' ? body : JSON.stringify(body))]);
  req.method = method;
  req.url = url;
  req.headers = {};
  if (body != null) req.headers['content-type'] = contentType;
  if (cookie) req.headers.cookie = cookie;
  req.socket = { remoteAddress, encrypted: false };
  const res = new MockResponse();
  const finished = new Promise((resolve, reject) => {
    res.once('finish', resolve);
    res.once('error', reject);
  });
  await handle(req, res);
  await finished;
  return { status: res.statusCode, headers: res.headers, body: res.body, bytes: res.bodyBuffer };
}
async function ensureTestClient(handle,{name,email,referralCode='',referralVisitorId=''}={}){
  const normalized=String(email).toLowerCase();let existing=testClientSessions.get(normalized);if(existing)return existing;
  const password=temporaryPassword(),remoteAddress=`127.0.0.${testClientIpSequence++}`;
  const registration=await call(handle,'POST','/api/client/register',{remoteAddress,body:{name,email:normalized,password,confirmPassword:password,student:false,referralCode,referralVisitorId}});
  let session;
  if(registration.status===201&&!asJson(registration).verificationRequired)session={cookie:sessionFrom(registration),password};
  else{
    assert.ok([201,409].includes(registration.status),`test client registration should work: ${registration.body}`);
    const login=await call(handle,'POST','/api/auth/login',{remoteAddress,body:{username:normalized,password,accountType:'client'}});
    assertStatus(login,200,'test client login');session={cookie:sessionFrom(login),password};
  }
  testClientSessions.set(normalized,session);return session;
}
const asJson = response => JSON.parse(response.body || '{}');
const sessionFrom = response => (Array.isArray(response.headers['Set-Cookie'])?response.headers['Set-Cookie']:[response.headers['Set-Cookie']||'']).map(value=>String(value).split(';')[0]).filter(Boolean).join('; ');
const assertStatus = (response, expected, label) => assert.equal(response.status, expected, `${label}: expected ${expected}, got ${response.status}; ${response.body}`);
async function enableManagementMfa(handle,cookie){
  const setup=await call(handle,'GET','/api/auth/mfa/setup',{cookie});assertStatus(setup,200,'management MFA setup');
  const secret=asJson(setup).secret,enabled=await call(handle,'POST','/api/auth/mfa/enable',{cookie,body:{code:currentTotp(secret)}});
  assertStatus(enabled,200,'management MFA enable');return secret;
}

