  const lifecycleClient=await ensureTestClient(app.handle,{name:'Lifecycle Test Client',email:'lifecycle-client@example.test'});
  const lifecycleOrderResponse=await call(app.handle,'POST','/api/leads',{cookie:lifecycleClient.cookie,remoteAddress:'127.0.0.49',body:{whatsappCountryCode:'+971',whatsappLocalNumber:'501234567',service:'web',category:'store',details:'A dedicated project lifecycle and delivery review test.',budget:'300 ILS',consent:'true',templateId:'web-thread-studio',templateAction:'order'}});
