  assertStatus(await call(app.handle,'PATCH',`/api/admin/leads/${lifecycleId}`,{cookie:adminCookie,body:{status:'active',contractAmount:300,developerUserId:developer.user.id,developerDueDate:'2026-12-01'}}),200,'owner assigns developer and agreed contract');
